def pin(p):
    p=Path(p);before=p.lstat()
    if not stat.S_ISREG(before.st_mode) or p.is_symlink():raise ValueError('regular packet source required')
    with os.fdopen(os.open(p,os.O_RDONLY|os.O_NOFOLLOW),'rb') as f:data=f.read()
    if p.lstat()!=before:raise ValueError('source drift')
    return {'path':str(p),'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()}
